import math

def summarise(samples):
    groups = {}
    for s in samples:
        groups.setdefault(s['label'], []).append(s)
    out = {}
    for label, rows in groups.items():
        ok = sorted(r['elapsed'] for r in rows if r['success'])
        errors = sum(1 for r in rows if not r['success'])
        p95 = ok[math.ceil(0.95 * len(ok)) - 1] if ok else None
        out[label] = {'count': len(rows), 'errors': errors, 'error_pct': round(100 * errors / len(rows), 1), 'p95': p95}
    return out

